function formatarData(valor: any) {
  if (valor?.toDate) {
    return valor.toDate().toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }
  if (typeof valor === 'string' && !isNaN(Date.parse(valor))) {
    return new Date(valor).toLocaleString('pt-BR');
  }
  return String(valor);
}

function converterDataEscala(valor: unknown): Date | null {
  if (typeof valor !== 'string') return null;

  const partes = valor.trim().match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
  if (!partes) return null;

  const dia = Number(partes[1]);
  const mes = Number(partes[2]) - 1;
  const ano = Number(partes[3]);
  const data = new Date(ano, mes, dia, 12);

  if (
    data.getFullYear() !== ano ||
    data.getMonth() !== mes ||
    data.getDate() !== dia
  ) {
    return null;
  }

  return data;
}

function formatarDataEscala(data: Date): string {
  const dia = String(data.getDate()).padStart(2, '0');
  const mes = String(data.getMonth() + 1).padStart(2, '0');

  return `${dia}/${mes}/${data.getFullYear()}`;
}

function datasSaoIguais(primeira: Date | null, segunda: Date): boolean {
  return !!primeira &&
    primeira.getFullYear() === segunda.getFullYear() &&
    primeira.getMonth() === segunda.getMonth() &&
    primeira.getDate() === segunda.getDate();
}

