export default function TelaDetalhesEscala(): JSX.Element {
  const route = useRoute<RotaDetalhesEscala>();
  const navigation = useNavigation();
  const id = route.params?.id;

  const [escala, setEscala] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [editando, setEditando] = useState(false);
  const [escalaEdit, setEscalaEdit] = useState<any>({});
  const [fotosIntegrantes, setFotosIntegrantes] = useState<Record<string, string>>(FOTOS_PADRAO);
  const [campoIntegranteAberto, setCampoIntegranteAberto] = useState<string | null>(null);
  const [buscaIntegrante, setBuscaIntegrante] = useState('');
  const [calendarioAberto, setCalendarioAberto] = useState(false);
  const [salvandoRespostaPresenca, setSalvandoRespostaPresenca] = useState(false);
  const [mesCalendario, setMesCalendario] = useState(() => {
    const hoje = new Date();
    return new Date(hoje.getFullYear(), hoje.getMonth(), 1, 12);
  });

  // Animação de alto relevo para os botões
  const animBtn1 = React.useRef(new Animated.Value(1)).current;
  const animBtn2 = React.useRef(new Animated.Value(1)).current;

  // Animação de chamada de atenção para o botão de confirmação de presença
  const pulseConfirmacao = React.useRef(new Animated.Value(1)).current;
  const animacaoFuncoesEscaladas = React.useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(animacaoFuncoesEscaladas, { toValue: 1, duration: 950, useNativeDriver: true }),
        Animated.timing(animacaoFuncoesEscaladas, { toValue: 0, duration: 950, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [animacaoFuncoesEscaladas]);

  useEffect(() => {
    const nomeUsuarioAtual = uidAtual ? UID_TO_NOME[uidAtual] : undefined;
    const nomeAtualNormalizado = nomeUsuarioAtual ? normalizarNomeIntegrante(nomeUsuarioAtual) : '';
    const usuarioEscaladoAgora = !!nomeAtualNormalizado && Array.from(CAMPOS_INTEGRANTES).some((campo) => {
      const valor = escala?.[campo];
      return typeof valor === 'string' && normalizarNomeIntegrante(valor) === nomeAtualNormalizado;
    });
    const presencaConfirmadaAgora = !!uidAtual && !!escala?.confirmacoesPresenca?.[uidAtual];

    if (usuarioEscaladoAgora && !presencaConfirmadaAgora) {
      const loop = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseConfirmacao, { toValue: 1.04, duration: 650, useNativeDriver: true }),
          Animated.timing(pulseConfirmacao, { toValue: 1, duration: 650, useNativeDriver: true }),
        ])
      );
      loop.start();
      return () => loop.stop();
    }
    pulseConfirmacao.setValue(1);
  }, [uidAtual, escala]);

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);

    if (!id) return;
    const carregarEscala = async () => {
      try {
        const docSnap = await getDoc(doc(db, 'escalas', id));
        if (docSnap.exists()) {
          const dadosEscala = docSnap.data();
          const dadosCorrigidos = corrigirNomesEscala(dadosEscala);
          setEscala(dadosCorrigidos);
          setEscalaEdit(dadosCorrigidos);
          if (escalaTemNomeCorrigido(dadosEscala, dadosCorrigidos)) {
            await updateDoc(doc(db, 'escalas', id), dadosCorrigidos);
          }
        } else {
          setEscala(null);
        }
      } catch (e) {
        setEscala(null);
      } finally {
        setLoading(false);
      }
    };
    carregarEscala();
  }, [id]);

  useEffect(() => {
    if (!id) return;

    const unsubscribe = onSnapshot(
      doc(db, 'escalas', id),
      snapshot => {
        if (!snapshot.exists()) return;

        const respostasAtualizadas = snapshot.data().confirmacoesPresenca || {};

        setEscala((anterior: any) => anterior ? {
          ...anterior,
          confirmacoesPresenca: respostasAtualizadas,
        } : anterior);

        setEscalaEdit((anterior: any) => ({
          ...anterior,
          confirmacoesPresenca: respostasAtualizadas,
        }));
      },
      error => console.log('Não foi possível acompanhar as respostas da escala:', error)
    );

    return () => unsubscribe();
  }, [id]);

  useEffect(() => {
    let fotosLocal: Record<string, string> = {};

    AsyncStorage.getItem('fotosUsuarios')
      .then(valor => {
        if (valor) fotosLocal = JSON.parse(valor);
      })
      .catch(() => {});

    const unsubscribe = onSnapshot(collection(db, 'presencas'), snapshot => {
      const fotosBanco: Record<string, string> = {};
      snapshot.docs.forEach(docSnap => {
        Object.entries(docSnap.data().fotosUsuarios || {}).forEach(([nome, foto]) => {
          if (typeof foto === 'string' && foto) {
            fotosBanco[nome] = foto;
          }
        });

        Object.entries(docSnap.data().fotosPorUid || {}).forEach(([uid, foto]) => {
          const nomeIntegrante = UID_TO_NOME[uid];

          if (nomeIntegrante && typeof foto === 'string' && foto) {
            fotosBanco[nomeIntegrante] = foto;
          }
        });
      });

      const fotosAtuais = { ...FOTOS_PADRAO, ...fotosBanco, ...fotosLocal };
      const fotosFiltradas = NOMES_USUARIOS.reduce((acc, nome) => {
        acc[nome] = fotosAtuais[nome] || `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`;
        return acc;
      }, {} as Record<string, string>);
      setFotosIntegrantes(fotosFiltradas);
    }, error => {
      console.log('Erro ao carregar fotos da presenca:', error);
    });

    return () => unsubscribe();
  }, []);

  // Máscara automÃ¡tica para data dd/mm/aaaa
  const handleChange = (campo: string, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      } else if (cleaned.length > 2) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      }
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: formatted }));
    } else {
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: valor }));
    }
  };

  const salvarAlterações = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    try {
      // O uniforme é configurado exclusivamente na tela Início.
      // Desconsidera o campo antigo sem apagá-lo do documento existente.
      const dadosEscalaSemUniforme = { ...escalaEdit };
      delete dadosEscalaSemUniforme.uniforme;

      await updateDoc(doc(db, 'escalas', id), {
        ...dadosEscalaSemUniforme,
        atualizadoEm: serverTimestamp(),
      });
      setEscala((anterior: any) => ({
        ...(anterior || {}),
        ...dadosEscalaSemUniforme,
      }));
      setEditando(false);
      Alert.alert('Sucesso', 'Escala atualizada com sucesso!');
      // incrementa contador remoto e local para sinalizar atualização
      const metaRef = doc(db, 'meta', 'escalas');
      try {
        await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
      } catch (err) {
        try {
          await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
        } catch (e2) {
          console.log('Erro ao incrementar contador remoto após editar escala', e2);
        }
      }
      try {
        const cur = await AsyncStorage.getItem('nova_escala');
        const num = cur ? parseInt(cur, 10) || 0 : 0;
        const novo = num + 1;
        await AsyncStorage.setItem('nova_escala', String(novo));
        await Notifications.setBadgeCountAsync(novo);
      } catch (e) {
        console.log('Erro ao setar contador/badge local depois de editar escala', e);
      }
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar as alterações.');
    }
  };

  const confirmarExclusao = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    confirmAction({
      title: 'Excluir Escala',
      message: `Deseja realmente excluir a escala "${escala?.data || escalaEdit?.data || id}"? Esta ação não pode ser desfeita.`,
      onConfirm: async () => {
        try {
          await deleteDoc(doc(db, 'escalas', id));
          Alert.alert('Sucesso', 'Escala excluída com sucesso!');
          // @ts-ignore
          if (navigation && navigation.goBack) navigation.goBack();
        } catch (error) {
          Alert.alert('Erro', 'Não foi possível excluir a escala.');
        }
      },
    });
  };

  const obterFuncoesDoUsuarioNaEscala = () => {
    if (!uidAtual) return [];

    const nomeUsuarioAtual = UID_TO_NOME[uidAtual];
    if (!nomeUsuarioAtual) return [];

    const nomeAtualNormalizado = normalizarNomeIntegrante(nomeUsuarioAtual);
    return Array.from(CAMPOS_INTEGRANTES)
      .filter(campo => {
        const valor = escala?.[campo];
        return typeof valor === 'string' && normalizarNomeIntegrante(valor) === nomeAtualNormalizado;
      })
      .map(labelComAcento);
  };

  const responderPresenca = async (status: 'confirmado' | 'negado') => {
    if (!id || !uidAtual) {
      Alert.alert('Atenção', 'Entre novamente na sua conta para responder à escala.');
      return;
    }

    if (salvandoRespostaPresenca) return;

    const nomeUsuarioAtual = UID_TO_NOME[uidAtual];
    const funcoes = obterFuncoesDoUsuarioNaEscala();
    if (!nomeUsuarioAtual || funcoes.length === 0) {
      Alert.alert('Escala', 'Seu usuário não aparece nesta escala.');
      return;
    }

    setSalvandoRespostaPresenca(true);

    try {
      const dataResposta = new Date();
      const respostaPresenca = {
        uid: uidAtual,
        nome: nomeUsuarioAtual,
        funcoes,
        status,
        atualizadoEm: dataResposta,
        ...(status === 'confirmado'
          ? { confirmadoEm: dataResposta }
          : { negadoEm: dataResposta }),
      };
      await updateDoc(doc(db, 'escalas', id), {
        [`confirmacoesPresenca.${uidAtual}`]: respostaPresenca,
      });
      setEscala((prev: any) => ({
        ...prev,
        confirmacoesPresenca: {
          ...(prev?.confirmacoesPresenca || {}),
          [uidAtual]: respostaPresenca,
        },
      }));
      setEscalaEdit((prev: any) => ({
        ...prev,
        confirmacoesPresenca: {
          ...(prev?.confirmacoesPresenca || {}),
          [uidAtual]: respostaPresenca,
        },
      }));
      Alert.alert(
        status === 'confirmado' ? 'Presença confirmada' : 'Presença negada',
        status === 'confirmado'
          ? 'Sua presença foi confirmada nesta escala.'
          : 'Sua ausência foi registrada nesta escala.'
      );
    } catch (error) {
      console.log('Não foi possível registrar a resposta da escala:', error);
      Alert.alert('Erro', 'Não foi possível salvar sua resposta. Tente novamente.');
    } finally {
      setSalvandoRespostaPresenca(false);
    }
  };

  const confirmarPresenca = () => responderPresenca('confirmado');
  const negarPresenca = () => responderPresenca('negado');

  const obterFotoIntegrante = (nome: string) => {
    if (!nome?.trim()) return null;

    const chaveIntegrante = obterChaveIntegrante(nome);
    return (chaveIntegrante && fotosIntegrantes[chaveIntegrante])
      || fotosIntegrantes[nome]
      || `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`;
  };

  const abrirSeletorIntegrante = (campo: string) => {
    setBuscaIntegrante('');
    setCampoIntegranteAberto(campo);
  };

  const selecionarIntegrante = (nome: string) => {
    if (!campoIntegranteAberto) return;

    handleChange(campoIntegranteAberto, nome.trim());
    setCampoIntegranteAberto(null);
    setBuscaIntegrante('');
  };

  const abrirCalendario = () => {
    const dataAtual = converterDataEscala(escalaEdit.data) || new Date();

    setMesCalendario(
      new Date(dataAtual.getFullYear(), dataAtual.getMonth(), 1, 12)
    );
    setCalendarioAberto(true);
  };

  const selecionarDataCalendario = (data: Date) => {
    handleChange('data', formatarDataEscala(data));
    setCalendarioAberto(false);
  };

  if (!id) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>ID da escala não informado.</Text>
        </View>
      </View>
    );
  }

  if (loading) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#ff9800" />
        </View>
      </View>
    );
  }

  if (!escala) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>Escala não encontrada.</Text>
        </View>
      </View>
    );
  }

  const camposOrdenados = [
    ...ordemCampos.filter((campo) => escala[campo] !== undefined && campo !== 'uniforme' && campo !== 'confirmacoesPresenca'),
    ...Object.keys(escala).filter((campo) => !ordemCampos.includes(campo) && campo !== 'uniforme' && campo !== 'confirmacoesPresenca'),
  ];

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);
  const funcoesUsuarioNaEscala = obterFuncoesDoUsuarioNaEscala();
  const camposUsuarioNaEscala = uidAtual && UID_TO_NOME[uidAtual]
    ? Array.from(CAMPOS_INTEGRANTES).filter(campo => {
      const valor = escala?.[campo];
      return typeof valor === 'string' && normalizarNomeIntegrante(valor) === normalizarNomeIntegrante(UID_TO_NOME[uidAtual]);
    })
    : [];
  const usuarioEstaEscalado = funcoesUsuarioNaEscala.length > 0;
  const respostaPresencaAtual = uidAtual ? escala?.confirmacoesPresenca?.[uidAtual] : null;
  const presencaConfirmada = !!respostaPresencaAtual && respostaPresencaAtual.status !== 'negado';
  const presencaNegada = respostaPresencaAtual?.status === 'negado';
  const integrantesDisponiveis = Array.from(
    new Set([
      ...NOMES_USUARIOS,
      ...Object.values(UID_TO_NOME),
      ...Object.keys(fotosIntegrantes),
    ])
  )
    .filter(nome => {
      const busca = normalizarNomeIntegrante(buscaIntegrante);
      return !busca || normalizarNomeIntegrante(nome).includes(busca);
    })
    .sort((primeiro, segundo) => primeiro.localeCompare(segundo, 'pt-BR'));

  const dataSelecionada = converterDataEscala(escalaEdit.data);
  const primeiroDiaCalendario = new Date(
    mesCalendario.getFullYear(),
    mesCalendario.getMonth(),
    1,
    12
  ).getDay();
  const diasNoMesCalendario = new Date(
    mesCalendario.getFullYear(),
    mesCalendario.getMonth() + 1,
    0,
    12
  ).getDate();
  const celulasCalendario = Array.from({ length: 42 }, (_, indice) => {
    const dia = indice - primeiroDiaCalendario + 1;

    return dia > 0 && dia <= diasNoMesCalendario
      ? new Date(mesCalendario.getFullYear(), mesCalendario.getMonth(), dia, 12)
      : null;
  });

  // Efeito de alto relevo nos botões
  const handlePressIn = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <LinearGradient colors={['#0B1630', '#151936', '#241A3D']} style={styles.bg}>
      {/* HEADER NEUMÓRFICO PERSONALIZADO */}
      <View style={styles.headerNeumorphic}>
        <LinearGradient
          colors={['#262A50', '#1B1F3D']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.headerRow}
        >
          {/* Botão Home à esquerda */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.navigate('Inicio')}
            activeOpacity={0.7}
          >
            <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
          </TouchableOpacity>

          {/* Título centralizado */}
          <View style={styles.headerCenterBox}>
            <Text style={styles.novaEscalaText}>Detalhes da Escala</Text>
          </View>

          {/* Botão Voltar à direita */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.goBack()}
            activeOpacity={0.7}
          >
            <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
          </TouchableOpacity>
        </LinearGradient>
      </View>
      {/* FIM HEADER */}

      <ScrollView contentContainerStyle={styles.container}>
        <View style={styles.card}>
          {usuarioEstaEscalado && (
            <Animated.View style={{ transform: [{ scale: pulseConfirmacao }] }}>
              <NeumorphicContainer
                style={styles.confirmacaoPresencaBox}
                borderColors={['transparent', 'transparent']}
                innerColors={presencaConfirmada ? ['#173B35', '#193D3D'] : presencaNegada ? ['#48212B', '#38202E'] : ['#222047', '#1B2444']}
                borderWidth={0}
              >
                <View style={styles.confirmacaoHeader}>
                  <LinearGradient
                    colors={presencaConfirmada ? ['#67E8F9', '#43E97B'] : presencaNegada ? ['#FF9AA8', '#F55367'] : ['#FFD166', '#FF9800']}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={styles.confirmacaoIconCircle}
                  >
                    <MaterialIcons name={presencaConfirmada ? 'check-circle' : presencaNegada ? 'cancel' : 'how-to-reg'} size={14} color="#111827" />
                  </LinearGradient>
                  <View style={styles.confirmacaoTextoBox}>
                    <Text style={styles.confirmacaoTitulo}>
                      {presencaConfirmada ? 'Presença confirmada' : presencaNegada ? 'Presença negada' : 'Confirme sua presença'}
                    </Text>
                    <Text style={styles.confirmacaoSubtitulo} numberOfLines={2}>
                      Você está escalado: {funcoesUsuarioNaEscala.join(', ')}.
                    </Text>
                    <View style={styles.confirmacaoFuncoes}>
                      {camposUsuarioNaEscala.map((campo, index) => (
                        <Animated.View
                          key={campo}
                          style={[
                            styles.confirmacaoFuncaoIcone,
                            {
                              opacity: animacaoFuncoesEscaladas.interpolate({
                                inputRange: [0, 1],
                                outputRange: [0.72, 1],
                              }),
                              transform: [{
                                translateY: animacaoFuncoesEscaladas.interpolate({
                                  inputRange: [0, 1],
                                  outputRange: [index % 2 === 0 ? 1 : -1, index % 2 === 0 ? -2 : 2],
                                }),
                              }],
                            },
                          ]}
                        >
                          <MaterialCommunityIcons name={nomeIconeCampo(campo)} size={14} color="#8CF7BF" />
                        </Animated.View>
                      ))}
                    </View>
                  </View>
                </View>
                <View style={styles.respostasPresencaLinha}>
                  <TouchableOpacity
                    onPress={confirmarPresenca}
                    activeOpacity={0.88}
                    disabled={salvandoRespostaPresenca || presencaConfirmada}
                    style={styles.respostaPresencaBotaoWrap}
                    accessibilityLabel="Confirmar presença na escala"
                  >
                    <LinearGradient
                      colors={presencaConfirmada ? ['#43E97B', '#2F9E6B'] : ['#173B35', '#215A47']}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 0 }}
                      style={[
                        styles.confirmacaoBotaoBorda,
                        styles.respostaPresencaConfirmarBorda,
                        presencaConfirmada && styles.confirmacaoBotaoBordaConfirmado,
                      ]}
                    >
                      <View style={styles.confirmacaoBotao}>
                        <MaterialIcons
                          name={presencaConfirmada ? 'done-all' : 'check-circle-outline'}
                          size={15}
                          color={presencaConfirmada ? '#FFFFFF' : '#8CF7BF'}
                        />
                        <Text style={[
                          styles.respostaPresencaConfirmarTexto,
                          presencaConfirmada && styles.confirmacaoBotaoTextoConfirmado,
                        ]}>
                          {presencaConfirmada ? 'Confirmado' : 'Confirmar'}
                        </Text>
                      </View>
                    </LinearGradient>
                  </TouchableOpacity>

                  <TouchableOpacity
                    onPress={negarPresenca}
                    activeOpacity={0.88}
                    disabled={salvandoRespostaPresenca || presencaNegada}
                    style={styles.respostaPresencaBotaoWrap}
                    accessibilityLabel="Negar presença na escala"
                  >
                    <LinearGradient
                      colors={presencaNegada ? ['#F87171', '#D94D61'] : ['#44222D', '#592735']}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 0 }}
                      style={[
                        styles.confirmacaoBotaoBorda,
                        styles.respostaPresencaNegarBorda,
                        presencaNegada && styles.respostaPresencaNegarAtivo,
                      ]}
                    >
                      <View style={styles.confirmacaoBotao}>
                        <MaterialIcons
                          name={presencaNegada ? 'cancel' : 'close'}
                          size={15}
                          color={presencaNegada ? '#FFFFFF' : '#FFADB4'}
                        />
                        <Text style={[
                          styles.respostaPresencaNegarTexto,
                          presencaNegada && styles.respostaPresencaNegarTextoAtivo,
                        ]}>
                          {presencaNegada ? 'Negado' : 'Negar'}
                        </Text>
                      </View>
                    </LinearGradient>
                  </TouchableOpacity>
                </View>
              </NeumorphicContainer>
            </Animated.View>
          )}

          {camposOrdenados.map((campo) => {
            const valorCampo = campoDataAuditoria(campo)
              ? formatarData(escala[campo])
              : CAMPOS_INTEGRANTES.has(campo)
                ? corrigirNomeIntegrante(String(escala[campo]))
                : String(escala[campo]);
            const fotoIntegrante = CAMPOS_INTEGRANTES.has(campo) ? obterFotoIntegrante(valorCampo) : null;
            const uidIntegrante = CAMPOS_INTEGRANTES.has(campo) ? obterUidPorNomeIntegrante(valorCampo) : undefined;
            const integranteTemNome = CAMPOS_INTEGRANTES.has(campo) && valorCampo.trim().length > 0;
            const respostaIntegrante = uidIntegrante ? escala?.confirmacoesPresenca?.[uidIntegrante] : null;
            const integranteConfirmou = !!respostaIntegrante && respostaIntegrante.status !== 'negado';
            const integranteNegou = respostaIntegrante?.status === 'negado';

            return (
              <NeumorphicContainer key={campo} style={styles.inputGroup}>
                <View style={styles.fieldRow}>
                  <View style={styles.fieldIconCircle}>
                    <MaterialCommunityIcons name={nomeIconeCampo(campo)} size={22} color="#111827" />
                  </View>
                  <Text style={styles.label} numberOfLines={1}>{labelComAcento(campo)}</Text>
                  {!editando || campoDataAuditoria(campo) ? (
                    <View
                      style={[
                        styles.valorBox,
                        fotoIntegrante && styles.valorBoxIntegrante,
                        integranteConfirmou && styles.valorBoxConfirmado,
                        integranteNegou && styles.valorBoxNegado,
                      ]}
                    >
                      {fotoIntegrante ? (
                        <View style={styles.valorIntegranteRow}>
                          <Image source={{ uri: fotoIntegrante }} style={styles.valorIntegranteFoto} />
                          <View style={styles.valorIntegranteTextos}>
                            <Text style={[styles.valor, styles.valorIntegranteNome]} numberOfLines={1}>
                              {valorCampo}
                            </Text>
                            {integranteTemNome && (
                              <Text style={[
                                styles.statusPresenca,
                                integranteConfirmou && styles.statusPresencaConfirmado,
                                integranteNegou && styles.statusPresencaNegado,
                              ]}>
                                {integranteConfirmou ? 'Confirmado' : integranteNegou ? 'Negado' : 'Pendente'}
                              </Text>
                            )}
                          </View>
                        </View>
                      ) : (
                        <>
                          <Text style={styles.valor} numberOfLines={2}>{valorCampo}</Text>
                          {integranteTemNome && (
                            <Text style={[
                              styles.statusPresenca,
                              integranteConfirmou && styles.statusPresencaConfirmado,
                              integranteNegou && styles.statusPresencaNegado,
                            ]}>
                              {integranteConfirmou ? 'Confirmado' : integranteNegou ? 'Negado' : 'Pendente'}
                            </Text>
                          )}
                        </>
                      )}
                    </View>
                  ) : null}
                </View>
                {editando && !campoDataAuditoria(campo) ? (
                  campo === 'data' ? (
                    <TouchableOpacity
                      style={styles.editorData}
                      onPress={abrirCalendario}
                      activeOpacity={0.82}
                      accessibilityLabel="Escolher a data da escala"
                    >
                      <View style={styles.editorDataIcone}>
                        <MaterialCommunityIcons name="calendar-month-outline" size={20} color="#67E8F9" />
                      </View>
                      <View style={styles.editorCampoTextos}>
                        <Text style={styles.editorCampoLegenda}>DATA DA ESCALA</Text>
                        <Text style={styles.editorCampoValor}>
                          {escalaEdit[campo] || 'Escolha uma data'}
                        </Text>
                      </View>
                      <MaterialCommunityIcons name="chevron-down" size={22} color="#9BB0D0" />
                    </TouchableOpacity>
                  ) : CAMPOS_INTEGRANTES.has(campo) ? (
                    <TouchableOpacity
                      style={styles.editorIntegrante}
                      onPress={() => abrirSeletorIntegrante(campo)}
                      activeOpacity={0.82}
                      accessibilityLabel={`Escolher integrante para ${labelComAcento(campo)}`}
                    >
                      {escalaEdit[campo] ? (
                        <Image
                          source={{ uri: obterFotoIntegrante(String(escalaEdit[campo])) || undefined }}
                          style={styles.editorIntegranteFoto}
                        />
                      ) : (
                        <View style={styles.editorIntegranteSemFoto}>
                          <MaterialCommunityIcons name="account-outline" size={22} color="#67E8F9" />
                        </View>
                      )}
                      <View style={styles.editorCampoTextos}>
                        <Text style={styles.editorCampoLegenda}>INTEGRANTE</Text>
                        <Text style={styles.editorCampoValor} numberOfLines={1}>
                          {escalaEdit[campo] || 'Selecione um integrante'}
                        </Text>
                      </View>
                      <MaterialCommunityIcons name="chevron-down" size={22} color="#9BB0D0" />
                    </TouchableOpacity>
                  ) : (
                    <TextInput
                      style={styles.input}
                      value={String(escalaEdit[campo] ?? '')}
                      onChangeText={text => handleChange(campo, text)}
                      placeholder={labelComAcento(campo)}
                      placeholderTextColor="#90caf9"
                      maxLength={60}
                      selectionColor="#ff9800"
                      keyboardType="default"
                      textAlign="left"
                      underlineColorAndroid="transparent"
                    />
                  )
                ) : null}
              </NeumorphicContainer>
            );
          })}

          {permitido && (
            <View style={styles.acoesAdminNeumorphic}>
              {!editando ? (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={() => {
                        setEscalaEdit({ ...escala });
                        setEditando(true);
                      }}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Editar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, styles.deleteButton]}
                      onPress={confirmarExclusao}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, { color: '#fff' }]}>Excluir</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              ) : (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={salvarAlterações}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Salvar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, styles.cancelButton]}
                      onPress={() => {
                        setEditando(false);
                        setEscalaEdit({ ...escala });
                      }}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, styles.cancelButtonText]}>Cancelar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              )}
            </View>
          )}
        </View>
      </ScrollView>

      <Modal
        visible={!!campoIntegranteAberto}
        transparent
        animationType="fade"
        onRequestClose={() => setCampoIntegranteAberto(null)}
      >
        <View style={styles.modalCamada}>
          <TouchableOpacity
            style={StyleSheet.absoluteFillObject}
            activeOpacity={1}
            onPress={() => setCampoIntegranteAberto(null)}
          />

          <View style={styles.modalPainel}>
            <View style={styles.modalCabecalho}>
              <View style={styles.modalTituloArea}>
                <Text style={styles.modalDestaque}>EQUIPE DE LOUVOR</Text>
                <Text style={styles.modalTitulo}>
                  {campoIntegranteAberto
                    ? labelComAcento(campoIntegranteAberto)
                    : 'Selecionar integrante'}
                </Text>
              </View>

              <TouchableOpacity
                style={styles.modalFechar}
                onPress={() => setCampoIntegranteAberto(null)}
                accessibilityLabel="Fechar seleção de integrantes"
              >
                <MaterialCommunityIcons name="close" size={21} color="#DCE8FB" />
              </TouchableOpacity>
            </View>

            <View style={styles.buscaIntegranteBox}>
              <MaterialCommunityIcons name="magnify" size={21} color="#67E8F9" />
              <TextInput
                style={styles.buscaIntegranteInput}
                value={buscaIntegrante}
                onChangeText={setBuscaIntegrante}
                placeholder="Buscar integrante pelo nome"
                placeholderTextColor="#8292AD"
                selectionColor="#67E8F9"
                autoCapitalize="words"
              />
            </View>

            <ScrollView
              style={styles.listaIntegrantesModal}
              contentContainerStyle={styles.listaIntegrantesConteudo}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              {integrantesDisponiveis.map(nome => {
                const selecionado = !!campoIntegranteAberto &&
                  normalizarNomeIntegrante(String(escalaEdit[campoIntegranteAberto] || '')) ===
                    normalizarNomeIntegrante(nome);

                return (
                  <TouchableOpacity
                    key={nome}
                    style={[
                      styles.opcaoIntegrante,
                      selecionado && styles.opcaoIntegranteSelecionada,
                    ]}
                    onPress={() => selecionarIntegrante(nome)}
                    activeOpacity={0.82}
                  >
                    <Image
                      source={{ uri: obterFotoIntegrante(nome) || undefined }}
                      style={styles.opcaoIntegranteFoto}
                    />
                    <View style={styles.opcaoIntegranteTextos}>
                      <Text style={styles.opcaoIntegranteNome} numberOfLines={1}>
                        {nome}
                      </Text>
                      <Text style={styles.opcaoIntegranteDescricao}>
                        Integrante do ministério
                      </Text>
                    </View>
                    {selecionado && (
                      <MaterialCommunityIcons name="check-circle" size={21} color="#43E97B" />
                    )}
                  </TouchableOpacity>
                );
              })}

              {!!buscaIntegrante.trim() && !integrantesDisponiveis.some(nome => (
                normalizarNomeIntegrante(nome) === normalizarNomeIntegrante(buscaIntegrante)
              )) && (
                <TouchableOpacity
                  style={styles.opcaoNomeDigitado}
                  onPress={() => selecionarIntegrante(buscaIntegrante)}
                  activeOpacity={0.82}
                >
                  <MaterialCommunityIcons name="account-plus-outline" size={21} color="#FFD166" />
                  <Text style={styles.opcaoNomeDigitadoTexto} numberOfLines={1}>
                    Usar "{buscaIntegrante.trim()}"
                  </Text>
                </TouchableOpacity>
              )}

              {!!campoIntegranteAberto && !!escalaEdit[campoIntegranteAberto] && (
                <TouchableOpacity
                  style={styles.opcaoLimparIntegrante}
                  onPress={() => selecionarIntegrante('')}
                  activeOpacity={0.82}
                >
                  <MaterialCommunityIcons name="account-remove-outline" size={20} color="#FF8B94" />
                  <Text style={styles.opcaoLimparIntegranteTexto}>Deixar campo em branco</Text>
                </TouchableOpacity>
              )}
            </ScrollView>
          </View>
        </View>
      </Modal>

      <Modal
        visible={calendarioAberto}
        transparent
        animationType="fade"
        onRequestClose={() => setCalendarioAberto(false)}
      >
        <View style={styles.modalCamada}>
          <TouchableOpacity
            style={StyleSheet.absoluteFillObject}
            activeOpacity={1}
            onPress={() => setCalendarioAberto(false)}
          />

          <View style={[styles.modalPainel, styles.calendarioPainel]}>
            <View style={styles.modalCabecalho}>
              <View style={styles.modalTituloArea}>
                <Text style={styles.modalDestaque}>ORGANIZAÇÃO DA ESCALA</Text>
                <Text style={styles.modalTitulo}>Escolher data</Text>
              </View>

              <TouchableOpacity
                style={styles.modalFechar}
                onPress={() => setCalendarioAberto(false)}
                accessibilityLabel="Fechar calendário"
              >
                <MaterialCommunityIcons name="close" size={21} color="#DCE8FB" />
              </TouchableOpacity>
            </View>

            <View style={styles.calendarioNavegacao}>
              <TouchableOpacity
                style={styles.calendarioNavegacaoBotao}
                onPress={() => setMesCalendario(anterior => (
                  new Date(anterior.getFullYear(), anterior.getMonth() - 1, 1, 12)
                ))}
                accessibilityLabel="Mês anterior"
              >
                <MaterialCommunityIcons name="chevron-left" size={25} color="#DCE8FB" />
              </TouchableOpacity>

              <View style={styles.calendarioMesArea}>
                <Text style={styles.calendarioMes}>
                  {MESES_CALENDARIO[mesCalendario.getMonth()]}
                </Text>
                <Text style={styles.calendarioAno}>{mesCalendario.getFullYear()}</Text>
              </View>

              <TouchableOpacity
                style={styles.calendarioNavegacaoBotao}
                onPress={() => setMesCalendario(anterior => (
                  new Date(anterior.getFullYear(), anterior.getMonth() + 1, 1, 12)
                ))}
                accessibilityLabel="Próximo mês"
              >
                <MaterialCommunityIcons name="chevron-right" size={25} color="#DCE8FB" />
              </TouchableOpacity>
            </View>

            <View style={styles.calendarioSemana}>
              {DIAS_SEMANA_CALENDARIO.map((dia, indice) => (
                <Text key={`${dia}-${indice}`} style={styles.calendarioDiaSemana}>
                  {dia}
                </Text>
              ))}
            </View>

            <View style={styles.calendarioGrade}>
              {celulasCalendario.map((data, indice) => {
                const selecionada = !!data && datasSaoIguais(dataSelecionada, data);
                const hoje = !!data && datasSaoIguais(new Date(), data);

                return (
                  <View key={`dia-${indice}`} style={styles.calendarioDiaArea}>
                    {data && (
                      <TouchableOpacity
                        style={[
                          styles.calendarioDia,
                          hoje && styles.calendarioDiaHoje,
                          selecionada && styles.calendarioDiaSelecionado,
                        ]}
                        onPress={() => selecionarDataCalendario(data)}
                        activeOpacity={0.78}
                      >
                        <Text
                          style={[
                            styles.calendarioDiaTexto,
                            hoje && styles.calendarioDiaTextoHoje,
                            selecionada && styles.calendarioDiaTextoSelecionado,
                          ]}
                        >
                          {data.getDate()}
                        </Text>
                      </TouchableOpacity>
                    )}
                  </View>
                );
              })}
            </View>

            <TouchableOpacity
              style={styles.calendarioBotaoHoje}
              onPress={() => selecionarDataCalendario(new Date())}
              activeOpacity={0.82}
            >
              <MaterialCommunityIcons name="calendar-today" size={19} color="#071426" />
              <Text style={styles.calendarioBotaoHojeTexto}>Selecionar hoje</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </LinearGradient>
  );
}

